Here's a complete implementation:

## XAML

```xml
<RefreshView IsRefreshing="{Binding IsRefreshing}"
             Command="{Binding RefreshCommand}">
    <CollectionView ItemsSource="{Binding Items}"
                    SelectionMode="Single"
                    SelectedItem="{Binding SelectedItem, Mode=TwoWay}"
                    SelectionChangedCommand="{Binding ItemSelectedCommand}">
        <CollectionView.ItemTemplate>
            <DataTemplate x:DataType="models:Item">
                <Grid Padding="12" ColumnDefinitions="Auto,*">
                    <Image Source="{Binding Icon}" WidthRequest="48" HeightRequest="48" />
                    <VerticalStackLayout Grid.Column="1" VerticalOptions="Center" Spacing="4">
                        <Label Text="{Binding Name}" FontAttributes="Bold" />
                        <Label Text="{Binding Description}" FontSize="12" TextColor="Gray" />
                    </VerticalStackLayout>
                </Grid>
            </DataTemplate>
        </CollectionView.ItemTemplate>
    </CollectionView>
</RefreshView>
```

## ViewModel

```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private ObservableCollection<Item> items = new();

    [ObservableProperty]
    private Item? selectedItem;

    [ObservableProperty]
    private bool isRefreshing;

    public ItemsViewModel(IApiService api, INavigationService nav)
    {
        _api = api;
        _nav = nav;
    }

    [RelayCommand]
    private async Task RefreshAsync()
    {
        var data = await _api.GetItemsAsync();
        Items = new ObservableCollection<Item>(data);
        IsRefreshing = false; // Must set to false when done
    }

    [RelayCommand]
    private async Task ItemSelectedAsync()
    {
        if (SelectedItem is null) return;

        await _nav.NavigateToAsync("DetailPage", new Dictionary<string, object>
        {
            { "Item", SelectedItem }
        });

        SelectedItem = null; // Reset so user can re-select same item
    }
}
```

## Key Bindings Explained

| Property | Binding | Purpose |
|---|---|---|
| `IsRefreshing` | `TwoWay` (default on RefreshView) | Controls spinner; set `false` when done |
| `Command` on RefreshView | `RefreshCommand` | Triggers API reload |
| `SelectedItem` | `TwoWay` | Tracks which item is tapped |
| `SelectionChangedCommand` | `ItemSelectedCommand` | Fires navigation logic |
| `ItemsSource` | `ObservableCollection<Item>` | Auto-updates UI on changes |

**Important notes:**
- Reset `SelectedItem = null` after navigation so the same item can be selected again.
- Set `IsRefreshing = false` at the end of your refresh command or the spinner spins forever.
- Use `ObservableCollection<T>`, never `List<T>`, for reactive UI updates.
